use ruff_python_parser::TokenKind;

/// Returns `true` if the name should be considered "ambiguous".
pub(super) fn is_ambiguous_name(name: &str) -> bool {
    name == "l" || name == "I" || name == "O"
}

/// Returns `true` if the given `token` is a non-logical token.
///
/// Unlike [`TokenKind::is_trivia`], this function also considers the indent, dedent and newline
/// tokens.
pub(super) const fn is_non_logical_token(token: TokenKind) -> bool {
    token.is_trivia()
        || matches!(
            token,
            TokenKind::Newline | TokenKind::Indent | TokenKind::Dedent
        )
}

/// Tracks progress through a PEP 695 type parameter list on a class, function,
/// or type alias definition.
#[derive(Debug, Clone, Copy)]
pub(crate) struct TypeParamsState {
    pub(crate) before_type_params: bool,
    pub(crate) in_type_params: bool,
    pub(crate) type_params_ended: bool,
    pub(crate) inner_square_brackets: u32,
}

impl Default for TypeParamsState {
    fn default() -> Self {
        Self {
            before_type_params: true,
            in_type_params: false,
            type_params_ended: false,
            inner_square_brackets: 0,
        }
    }
}

